import {
  Group,
  PlaneGeometry,
  MeshBasicNodeMaterial,
  Mesh,
  Texture,
  Color,
} from 'three/webgpu';
import {
  uv,
  mix,
  vec4,
  vec3,
  uniform,
  mul,
  add,
  rand,
  texture,
  Fn,
} from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  // ----- extract text content -----
  const items =
    config.textContent ??
    config.intent?.visualSpec?.textContent ??
    [];
  const headline = items.find((t) => t.role === 'headline');
  const labelText = headline?.text ?? 'Pricing 1';
  // use typography.fontSize if present, otherwise fallback to design scale
  const fontSize = headline?.typography?.fontSize ?? 0.34; // scene units (headline scale)

  // ----- colors (normalized) -----
  const paperCol = new Color('#e8ecf2');
  const surfaceCol = new Color('#0b0b10');
  const paperVec = vec3(paperCol.r, paperCol.g, paperCol.b);
  const surfaceVec = vec3(surfaceCol.r, surfaceCol.g, surfaceCol.b);

  // ----- group -----
  const group = new Group();

  // ----- plane geometry -----
  const geometry = new PlaneGeometry(2.5, 1.6); // prose from 512x320 aspect

  // ----- texture uniform (placeholder) -----
  const textureUniform = uniform(new Texture());

  // ----- custom fragment node (gradient + texture blend + grain) -----
  const fragmentNode = Fn(() => {
    const texColor = texture(textureUniform, uv());
    const gradY = uv().y;
    const gradColor = mix(surfaceVec, paperVec, gradY);
    const blended = mix(texColor.rgb, gradColor, 0.6);
    const grain = mul(rand(mul(uv(), 1000.0)), 0.04);
    const finalColor = blended.add(vec3(grain));
    return vec4(finalColor, 1.0);
  })();

  // ----- material -----
  const material = new MeshBasicNodeMaterial();
  material.fragmentNode = fragmentNode;
  material.needsUpdate = true;

  const mesh = new Mesh(geometry, material);
  mesh.position.z = 0;
  group.add(mesh);

  // ----- load texture async -----
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      textureUniform.value = tex;
      material.needsUpdate = true;
    });
  }

  // ----- text label -----
  const textObj = ctx.fontAtlas.createText(labelText, {
    fontSize: fontSize,
    color: '#e8ecf2',
    align: 'center',
    maxWidthPx: 250, // keep within plane width
  });
  textObj.position.z = 0.02;
  // scale text to fit within plane: adjust if needed
  group.add(textObj);

  // ----- no primitives (static) -----

  // ----- cleanup -----
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (textureUniform.value) textureUniform.value.dispose();
    // dispose text children
    textObj.traverse((child) => {
      if (child.isMesh) {
        child.geometry.dispose();
        if (child.material) child.material.dispose();
      }
    });
  };

  // ----- handlers (none) -----
  group.userData.handlers = {};

  return group;
}
